const paymentMethods=['Pix','Transferência bancária','TED','Boleto','Dinheiro','Outro'];
function canRecordPayment(x){return canManage('Comissões')&&(!x.payer||x.payer===currentUser);}
function billingPolicy(p){if(p.type==='Avulsa')return {mode:'once',months:1};const mode=p.billingMode||'ongoing',months=mode==='fixed'?p.billingMonths:12;if(!['ongoing','fixed'].includes(mode)||!Number.isInteger(months)||months<1||months>120)throw Error('Revise a duração da cobrança no produto.');return {mode,months};}
function billingLabel(p){if(!p)return '';const b=billingPolicy(p);return b.mode==='once'?'Cobrança única':b.mode==='fixed'?b.months+' mensalidades':'Mensal enquanto o contrato estiver ativo';}
// All money is rounded at each charge and commission event.
const roundMoney=n=>Math.round((n+Number.EPSILON)*100)/100;
const uid=prefix=>prefix+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);
function localToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function addMonths(date,n){const [y,m,d]=date.split('-').map(Number);const first=new Date(Date.UTC(y,m-1+n,1));const last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();return `${first.getUTCFullYear()}-${String(first.getUTCMonth()+1).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`;}
if(!state.invoices){state.invoices=[];state.commissionPayments={};for(const c of state.contracts){c.saleId='legacy-'+c.id;c.legacy=true;const base={contractId:c.id,company:c.company,due:c.start,paidAt:c.paid?c.start:null,legacy:true};state.invoices.push({...base,id:uid('inv'),kind:'fee',fee:c.fee,amount:c.monthly});if(c.fee===1&&c.setup>0)state.invoices.push({...base,id:uid('inv'),kind:'setup',fee:0,amount:c.setup});}save();}state.commissionPayments??={};
let saleDraft=null,invoiceMonth='all',commissionMonth='all',invoiceQuery='',commissionQuery='',commissionPerson='all',commissionStatus='all',commissionContract='all',commissionType='all',commissionDateBasis='due';
function invoiceContract(i){return state.contracts.find(c=>c.id===i.contractId)}
function scopedInvoices(){return state.invoices.filter(i=>!i.archived||i.paidAt).filter(i=>{const c=invoiceContract(i);return c&&(!c.archived&&(!c.reviewStatus||c.reviewStatus==='approved')||i.paidAt)&&canAccess(c.company)&&(company==='all'||company===c.company)})}
function rawLedger(){let rows=[];for(const i of state.invoices){let c=invoiceContract(i);if(!c)continue;let r=c.rules;function line(who,key,amount,condition,label,rate){amount=roundMoney(amount);if(!who||amount<=0)return;let id=i.id+'-'+key;if((i.archived||c.archived||c.reviewStatus&&c.reviewStatus!=='approved')&&!state.commissionPayments[id])return;rows.push({id,role:key,invoice:i,contract:c,person:who,amount,label,rate,paidAt:state.commissionPayments[id]||null,released:!!i.paidAt&&condition&&c.status==='Ativo'&&!i.archived&&!c.archived&&(!c.reviewStatus||c.reviewStatus==='approved')});}if(i.kind==='fee'){let pct=i.fee===1?r.first:i.fee<=r.months?r.next:0;line(c.seller,'seller',i.amount*pct/100,true,`Fee ${i.fee} · venda`,pct);if(i.fee===1)line(c.dev,'dev',i.amount*r.devFirst/100,true,'Primeiro fee · desenvolvimento',r.devFirst);if(c.partner&&i.fee<=r.months)line(c.partner,'partner',i.amount*(r.partner||0)/100,true,'Fee · parceiro',r.partner||0);}else{line(c.seller,'seller',i.amount*r.setup/100,c.started,'Implementação · venda',r.setup);let pool=i.amount*r.devSetup/100,half=roundMoney(pool/2);line(c.dev,'dev-start',half,c.started,'Implementação · início',r.devSetup/2);line(c.dev,'dev-accept',roundMoney(pool)-half,c.accepted,'Implementação · aceite',r.devSetup/2);}}return rows.concat(extraCommissionRows());}
function visibleLedger(){return ledger().filter(x=>canAccess(x.contract.company)&&(company==='all'||company===x.contract.company)&&(canManage()||x.person===currentUser)).sort(compareCommissionReceipt);}
function compareCommissionReceipt(a,b){const receivedA=a.invoice.paidAt,receivedB=b.invoice.paidAt;if(receivedA&&!receivedB)return -1;if(!receivedA&&receivedB)return 1;return (receivedA||a.invoice.due).localeCompare(receivedB||b.invoice.due)||a.invoice.due.localeCompare(b.invoice.due)||contractCode(a.contract).localeCompare(contractCode(b.contract))||a.id.localeCompare(b.id);}
// Keep dashboard totals in sync with the event ledger.
commission=function(c){const rows=ledger().filter(x=>x.contract.id===c.id);return {sales:roundMoney(rows.filter(x=>x.role==='seller').reduce((a,x)=>a+x.amount,0)),dev:roundMoney(rows.filter(x=>x.role.startsWith('dev')).reduce((a,x)=>a+x.amount,0))};};

function monthFilter(id,label,current,dates,onchange){const periods=[...new Set(dates.map(d=>d.slice(0,7)))].sort();return `<div class="filters"><label for="${id}">${label}</label><select id="${id}" onchange="${onchange}=this.value;render()"><option value="all">Todos os meses</option>${periods.map(p=>`<option value="${p}" ${p===current?'selected':''}>${esc(periodLabel(p))}</option>`).join('')}</select></div>`;}
function renderInvoices(){let list=scopedInvoices().filter(i=>(invoiceMonth==='all'||i.due.startsWith(invoiceMonth))&&matchesContract(invoiceContract(i),invoiceQuery)).sort((a,b)=>a.due.localeCompare(b.due));let received=list.filter(i=>i.paidAt).reduce((a,i)=>a+i.amount,0);return title('Recebíveis','Cada mensalidade, venda avulsa e parcela de implementação tem seu próprio recebimento.',canSell()?btn('+ Nova venda','newSale()'):'')+metric([['Cobranças no filtro',list.length,'Por vencimento'],['Previsto',money(list.reduce((a,i)=>a+i.amount,0)),'Cobranças cadastradas'],['Recebido',money(received),'Pagamento confirmado'],['Em aberto',money(list.filter(i=>!i.paidAt&&invoiceContract(i).status==='Ativo').reduce((a,i)=>a+i.amount,0)),'Contratos ativos']])+monthFilter('invoiceMonth','Vencimento',invoiceMonth,scopedInvoices().map(i=>i.due),'invoiceMonth')+financeSearch('invoiceSearch',invoiceQuery,'invoiceQuery')+`<section class="panel">${table(['Cliente / empresa','Produto / cobrança','Vencimento','Valor','Situação','Ações'],list.map(i=>{let c=invoiceContract(i);return [`${contractReference(c)}<div>${esc(c.client)}</div><div class="small">${esc(companyName(c.company))}</div>`,`${esc(product(c.product)?.name)}<div class="small">${i.kind==='fee'?(product(c.product)?.type==='Avulsa'?'Venda avulsa':'Mensalidade '+i.fee):'Implementação · parcela '+(i.part||1)}${i.legacy?' · referência migrada':''}</div>`,esc(i.due),money(i.amount),`<span class="pill ${!i.paidAt?'amber':''}">${i.paidAt?'Recebido em '+esc(i.paidAt):c.status==='Ativo'?'Em aberto':'Contrato cancelado'}</span>`,`<div class="catalog-actions">${btn(i.paidAt?'Desfazer recebimento':'Registrar recebimento',`receiveInvoice('${i.id}')`,!!i.paidAt)}${productAction('edit','Editar recebível',`editInvoice('${i.id}')`)}${productAction('delete','Excluir recebível',`archiveInvoice('${i.id}')`)}</div>`]}))}</section><div class="notice">Registro local de pagamentos integrais. Implementação e mensalidade são independentes. Para gerar mensalidades além do prazo inicial, abra o contrato e use “Adicionar próxima mensalidade”. Editar uma cobrança altera apenas seu valor e vencimento; o valor mensal do contrato permanece preservado.</div>`+archivedInvoicesPanel();}
function renderCommissionLedger(){const all=visibleLedger();if(commissionPerson!=='all'&&!all.some(x=>x.person===commissionPerson))commissionPerson='all';if(commissionContract!=='all'&&!all.some(x=>String(x.contract.id)===commissionContract))commissionContract='all';const rows=all.filter(matchesCommissionFilters);let total=rows.reduce((a,x)=>a+x.amount,0),paid=rows.filter(x=>x.paidAt).reduce((a,x)=>a+x.amount,0),released=rows.filter(x=>x.released&&!x.paidAt).reduce((a,x)=>a+x.amount,0);return title(canManage()?'Comissões':'Minhas comissões','Por recebimento: mais antigos primeiro; não recebidos ao final.',`<div class="commission-toolbar">${btn('Gerar PDF','generateCommissionPdf()',true)}${canManage()?btn('+ Comissão extraordinária','newExtraCommission()'):''}</div>`)+metric([['Total no filtro',money(total),'Inclui valores pagos e previstos'],['A pagar',money(released),'Condições atendidas'],['Paga',money(paid),'Pagamento registrado'],['Pendente',money(roundMoney(total-paid-released)),'Aguardando condições']])+`<div class="commission-filters">`+commissionDateFilter()+monthFilter('commissionMonth','Mês',commissionMonth,all.map(commissionDate).filter(Boolean),'commissionMonth')+financeSearch('commissionSearch',commissionQuery,'commissionQuery')+`</div>`+commissionFilterBar(all)+`<section class="panel commission-panel"><div class="commission-result-count">${rows.length} lançamento(s) encontrado(s) · totais conforme os filtros</div><table class="commission-table"><colgroup><col style="width:24%"><col style="width:17%"><col style="width:14%"><col style="width:12%"><col style="width:15%"><col style="width:18%"></colgroup><thead><tr><th>Contrato</th><th>Pessoa</th><th>Valor</th><th>Status</th><th title="Responsável pelo pagamento">Pagador</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${contractReference(x.contract)}<div class="commission-client">${esc(x.contract.client)}</div><div class="small">${esc(companyName(x.contract.company))} · ${esc(product(x.contract.product)?.name)}</div>${x.contract.archived?'<div class="small">Contrato arquivado · pagamento preservado</div>':''}</td><td><strong>${esc(userName(x.person))}</strong><div class="small">${esc(x.label.replace('Primeiro fee · desenvolvimento','1º fee · dev').replace('Implementação','Implant.').replace('Extraordinária','Extra'))}</div><div class="small">${x.invoice.paidAt?'Recebido '+compactDate(x.invoice.paidAt):'Vence '+compactDate(x.invoice.due)}</div></td><td><strong class="commission-value">${money(x.amount)}</strong><div class="small">${x.adjusted?'Ajustada':x.manual?'Extra':x.rate+'%'}</div></td><td><span class="pill ${!x.released&&!x.paidAt?'amber':''}">${x.paidAt?'Paga':x.released?'Liberada':'Prevista'}</span>${x.paidAt?`<div class="small">${compactDate(x.paidAt)}</div>`:''}</td><td>${esc(x.payer?userName(x.payer):'—')}</td><td><div class="commission-action-stack"><div class="catalog-actions">${canManage()?`${canRecordPayment(x)?(x.paidAt?productAction('restore','Desfazer pagamento',`payCommission('${x.id}')`):x.released?productAction('check','Registrar pagamento',`payCommission('${x.id}')`):''):''}${productAction('edit','Editar comissão',`editCommission('${x.id}')`)}${productAction('delete','Excluir comissão',`archiveCommission('${x.id}')`)}`:''}</div><button type="button" class="commission-detail-button" aria-expanded="false" aria-controls="detail-${x.id}" onclick="toggleCommissionDetail(this,'detail-${x.id}')">Detalhes ⌄</button></div></td></tr><tr class="commission-detail-row" id="detail-${x.id}" hidden><td colspan="6"><div class="commission-detail-grid"><div><span class="eyebrow">Cálculo</span><p>${x.manual?'Comissão extraordinária de valor fixo':money(x.invoice.amount)+' × '+x.rate+'% · política v'+x.contract.version}</p>${x.adjusted?`<p>Original: ${money(x.originalAmount)} · ajustada: ${money(x.amount)}</p><p>Motivo: ${esc(x.editReason)}</p>`:''}${x.reason?`<p>${esc(x.reason)}</p>`:''}</div><div><span class="eyebrow">Datas</span>${commissionDates(x)}</div><div><span class="eyebrow">Pagamento</span><p>${esc(x.payer?userName(x.payer):'Responsável não definido')}</p><p>Meio: ${esc(x.paymentMethod||'Não informado')}</p><p>${x.paidAt?'Pago em '+compactDate(x.paidAt):x.plannedDate?'Previsto para '+compactDate(x.plannedDate):'Sem previsão de pagamento'}</p></div></div></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhuma comissão neste filtro.</td></tr>'}</tbody></table></section><p class="small" style="margin-top:14px">Abra “Detalhes” para consultar cálculo, datas e observações. Editar afeta somente este lançamento; exclusões podem ser restauradas.</p>`+archivedCommissionPanel();}
function compactDate(date){if(!date)return '—';const [y,m,d]=date.split('-');return d+'/'+m+'/'+y;}
function toggleCommissionDetail(button,id){const row=document.getElementById(id);row.hidden=!row.hidden;button.setAttribute('aria-expanded',String(!row.hidden));button.textContent=row.hidden?'Detalhes ⌄':'Recolher ⌃';}

function receiveInvoice(id){if(!canManage('Recebíveis'))return;let i=state.invoices.find(x=>x.id===id),c=i&&invoiceContract(i);if(!c||i.archived||!canAccess(c.company))return;if(i.paidAt){if(ledger().some(x=>x.invoice.id===id&&x.paidAt))return toast('Desfaça o pagamento das comissões vinculadas antes do recebimento.');i.paidAt=null;save();render();return toast('Recebimento desfeito.');}if(c.status!=='Ativo')return toast('Reative o contrato para receber.');show(`<h2>Registrar recebimento</h2><p>${esc(c.client)} · ${money(i.amount)}</p><form>${field('date','Data do recebimento',localToday(),'date','required')}${actions()}</form>`,f=>{let date=f.get('date');if(!validDate(date)||date>localToday())return toast('Informe uma data válida, até hoje.');i.paidAt=date;closeSaved('Recebimento confirmado; comissões atualizadas.');});}
function payCommission(id){if(!canManage('Comissões'))return;let x=ledger().find(x=>x.id===id);if(!x||!canAccess(x.contract.company))return;if(!canRecordPayment(x))return toast('Somente o responsável designado pode registrar ou desfazer este pagamento.');if(x.paidAt){delete state.commissionPayments[id];delete state.commissionPaymentDetails[id];commissionHistory(id,'undo-payment');save();render();return toast('Pagamento da comissão desfeito.');}if(!x.released)return toast('Esta comissão ainda não está liberada.');const people=paymentPeople(x.contract.company,x.payer).filter(u=>u.id===currentUser);show(`<h2>Registrar pagamento da comissão</h2><p>${esc(contractCode(x.contract))} · ${esc(userName(x.person))} · ${money(x.amount)}</p><p>${esc(x.label)} · cliente recebeu em ${esc(x.invoice.paidAt)}</p><form><div class="formgrid">${select('payer','Responsável pelo pagamento',people.map(u=>[u.id,u.name]),x.payer||currentUser)}${field('date','Data do pagamento',localToday(),'date','required')}${select('method','Meio de pagamento',[['','Selecione'],...paymentMethods.map(v=>[v,v])],'').replace('<select ','<select required ' )}</div>${actions()}</form>`,f=>{try{recordCommissionPayment(id,f.get('date'),f.get('payer'),f.get('method'));closeSaved('Pagamento da comissão registrado com responsável e data.');}catch(e){toast(e.message)}});}

function validDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&!isNaN(Date.parse(d))&&new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d;}
function newSale(seed){if(!canSell())return;let cid=seed?.company||(company==='all'?allowed()[0]?.id:company);if(!cid||!canAccess(cid))return;const ps=state.products.filter(p=>p.company===cid&&!p.archived);if(!ps.length)return toast('Nenhum produto ativo nesta empresa. Solicite o cadastro ao administrador.');saleDraft={company:cid,items:[{product:seed?.product||ps[0]?.id||'',value:seed?.monthly??product(seed?.product||ps[0]?.id)?.baseMonthly??0,setup:seed?.setup??product(seed?.product||ps[0]?.id)?.baseSetup??0,parts:1,seller:seed?.seller||'',dev:seed?.dev||'',partner:seed?.partner||''}],seed};show(`<h2>Nova venda</h2><p>${['Vendedor','Colaborador'].includes(user().role)?'Salve o rascunho, anexe os documentos e envie para validação da empresa.':'Uma venda, vários produtos e políticas preservadas por item.'}</p><form id="saleForm"><div class="formgrid" style="margin-top:18px">${select('company','Empresa',allowed().map(c=>[c.id,c.name]),cid)}${field('client','Cliente',seed?.client||'','text','required')}${field('date','Data da venda / ativação',localToday(),'date','required')}${field('due','Primeiro vencimento',localToday(),'date','required')}</div><div id="saleItems"></div><div class="actions" style="justify-content:flex-start">${btn('+ Adicionar produto','addSaleItem()',true)}</div><div class="notice">Os valores base do produto são preenchidos automaticamente e podem ser negociados nesta venda. Valores líquidos comissionáveis. NFS-e e extras devem ser cadastrados como produtos próprios, com sua política. Vendas avulsas geram uma cobrança; implementação pode ser parcelada. Sem integração bancária neste protótipo.</div><div id="saleSummary"></div>${['Vendedor','Colaborador'].includes(user().role)?actions().replace('>Salvar</button>','>Salvar rascunho</button>'):actions()}</form>`,f=>submitSale(f));document.getElementById('f_company').onchange=e=>{saleDraft.company=e.target.value;const ps=state.products.filter(p=>p.company===saleDraft.company&&!p.archived);saleDraft.items=[{product:ps[0]?.id||'',value:ps[0]?.baseMonthly??0,setup:ps[0]?.baseSetup??0,parts:1,seller:'',dev:'',partner:''}];renderSaleItems();};renderSaleItems();}
function addSaleItem(){if(!saleDraft)return;let p=state.products.find(p=>p.company===saleDraft.company&&!p.archived);saleDraft.items.push({product:p?.id||'',value:p?.baseMonthly??0,setup:p?.baseSetup??0,parts:1,seller:'',dev:'',partner:''});renderSaleItems();}
function updateSaleItem(index,key,value){let item=saleDraft.items[index];item[key]=['value','setup','parts'].includes(key)?Number(value):value;if(key==='product'){const p=product(value);item.value=p?.baseMonthly??0;item.setup=p?.baseSetup??0;delete item.rules;renderSaleItems();}else renderSaleSummary();}
function ruleForItem(item){return item.rules||{...zeroRules,...product(item.product)?.rules,partner:product(item.product)?.rules?.partner||0};}
function renderSaleItems(){const ps=state.products.filter(p=>p.company===saleDraft.company&&!p.archived);let people=state.users.filter(u=>u.active),participantOptions=[['','Não atribuído'],...people.map(u=>[u.id,u.name])];document.getElementById('saleItems').innerHTML=saleDraft.items.map((item,i)=>{let r=ruleForItem(item);return `<section class="panel" style="margin-top:16px"><div class="panelhead"><h2>Produto ${i+1}</h2>${saleDraft.items.length>1?btn('Remover',`saleDraft.items.splice(${i},1);renderSaleItems()`,true):''}</div><div class="formgrid">${select('item'+i,'Produto',ps.map(p=>[p.id,p.name+' · '+p.type]),item.product).replace('<select ',`<select onchange="updateSaleItem(${i},'product',this.value)" `)}${[['value','Mensalidade / venda líquida (R$)'],['setup','Implementação (R$)'],['parts','Parcelas da implementação']].map(([k,l])=>field('item'+i+k,l,item[k],'number',`required min="${k==='parts'?1:0}" ${k==='parts'?'max="60"':''} step="${k==='parts'?1:'.01'}" oninput="updateSaleItem(${i},'${k}',this.value)"`)).join('')}${(canManage()?[['seller','Vendedor'],['dev','Desenvolvedor'],['partner','Parceiro (opcional)']]:[]).map(([k,l])=>select('item'+i+k,l,participantOptions,item[k]).replace('<select ',`<select oninput="updateSaleItem(${i},'${k}',this.value)" `)).join('')}</div><p class="small">${esc(billingLabel(product(item.product)))}</p>${canManage()?`<details style="margin-top:15px"><summary>Percentuais da venda · política v${product(item.product)?.version||1}</summary><p class="small">Exceções ficam guardadas apenas nesta venda. Parceiro: percentual informado aqui, por até o limite de fees.</p><div class="formgrid">${Object.entries({first:'Venda · 1º fee (%)',next:'Venda · próximos fees (%)',setup:'Venda · implementação (%)',devFirst:'Dev · 1º fee (%)',devSetup:'Dev · implementação (%)',partner:'Parceiro · mensalidade (%)',months:'Último fee comissionável'}).map(([k,l])=>field('rule'+i+k,l,r[k]||0,'number',`required min="${k==='months'?1:0}" max="${k==='months'?120:100}" step="${k==='months'?1:'.1'}" oninput="saleDraft.items[${i}].rules={...ruleForItem(saleDraft.items[${i}]),${k}:Number(this.value)};renderSaleSummary()"`)).join('')}</div></details>`:'<p class="small">Vendedor: '+esc(user().name)+' · Comissão calculada pela política do produto.</p>'}</section>`}).join('');renderSaleSummary();}
function renderSaleSummary(){if(!saleDraft)return;let m=saleDraft.items.filter(i=>product(i.product)?.type==='Recorrente').reduce((a,i)=>a+i.value,0),setup=saleDraft.items.reduce((a,i)=>a+i.setup,0);document.getElementById('saleSummary').innerHTML=`<div class="notice">Resumo: ${saleDraft.items.length} produto(s) · MRR ${money(m)} · implementação ${money(setup)}. ${['Vendedor','Colaborador'].includes(user().role)?'O rascunho não entra no MRR ativo. As comissões ficarão disponíveis após aprovação da empresa.':'As cobranças e comissões serão geradas ao salvar.'}</div>`;}
function buildSale(data){if(!canManage('Contratos')||!canAccess(data.company))throw Error('Empresa sem acesso.');if(!data.client.trim()||!validDate(data.date)||!validDate(data.due)||data.due<data.date)throw Error('Revise cliente, datas e quantidade de mensalidades.');if(!data.items.length)throw Error('Inclua um produto.');let contracts=[],invoices=[],saleId=uid('sale');for(let item of data.items){if(!item.seller)throw Error('Informe o vendedor responsável em cada produto.');let p=product(item.product),r=structuredClone(ruleForItem(item));if(!p||p.archived||p.company!==data.company)throw Error('Os produtos devem pertencer à empresa selecionada.');if(![item.value,item.setup,item.parts].every(Number.isFinite)||item.value<0||item.setup<0||!Number.isInteger(item.parts)||item.parts<1||item.parts>60)throw Error('Revise valores e parcelas.');if(Object.entries(r).filter(([k])=>['first','next','setup','devFirst','devSetup','partner','months'].includes(k)).some(([k,v])=>!Number.isFinite(v)||v<(k==='months'?1:0)||v>(k==='months'?120:100))||!Number.isInteger(r.months)||r.setup+r.devSetup>100||r.first+r.devFirst+r.partner>100||r.next+r.partner>100)throw Error('Revise a distribuição dos percentuais.');if([item.seller,item.dev,item.partner].some(id=>id&&!state.users.some(u=>u.id===id&&u.active)))throw Error('Participante inválido.');const billing=billingPolicy(p);let c={billingMode:billing.mode,billingMonths:billing.mode==='fixed'?billing.months:null,id:Date.now()*1000+Math.floor(Math.random()*900)+contracts.length,company:data.company,saleId,client:data.client.trim(),product:p.id,plan:p.name,monthly:roundMoney(item.value),setup:roundMoney(item.setup),seller:item.seller,dev:item.dev,partner:item.partner,start:data.date,status:'Ativo',fee:1,paid:false,started:false,accepted:false,rules:r,version:p.version,firstDue:data.due,schedule:true};contracts.push(c);const base={contractId:c.id,company:c.company,paidAt:null};for(let n=0;n<billing.months;n++)invoices.push({...base,id:uid('inv'),kind:'fee',fee:n+1,amount:c.monthly,due:addMonths(data.due,n)});if(c.setup>0&&item.parts>Math.round(c.setup*100))throw Error('O valor da implementação deve permitir parcelas de pelo menos R$ 0,01.');if(c.setup>0){const total=Math.round(c.setup*100),part=Math.floor(total/item.parts);for(let n=0;n<item.parts;n++)invoices.push({...base,id:uid('inv'),kind:'setup',part:n+1,fee:0,amount:(part+(n===item.parts-1?total-part*item.parts:0))/100,due:addMonths(data.due,n)});}}assignContractCodes(contracts);return {contracts,invoices};}
function submitSale(f){try{let result=buildSale({company:f.get('company'),client:f.get('client'),date:f.get('date'),due:f.get('due'),items:saleDraft.items});state.contracts.push(...result.contracts);state.invoices.push(...result.invoices);saleDraft=null;page='Recebíveis';invoiceMonth='all';closeSaved('Venda salva; cobranças e comissões previstas geradas.');}catch(e){toast(e.message);}}
function editContract(id){if(!id)return newSale();if(!canManage('Contratos'))return;let c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company))return;if(c.reviewStatus&&c.reviewStatus!=='approved')return openSalePortal(c.id);show(`<h2>Editar contrato · ${esc(contractCode(c))}</h2><p>${esc(companyName(c.company))} · política v${c.version}</p><form><div class="formgrid" style="margin-top:18px">${field('client','Cliente',c.client,'text','required')}${field('plan','Plano / descrição',c.plan||product(c.product)?.name||'','text','required')}${select('product','Produto vinculado',state.products.filter(p=>p.company===c.company&&(!p.archived||p.id===c.product)).map(p=>[p.id,p.name]),c.product).replace('<select ', '<select onchange="document.getElementById(\'f_plan\').value=product(this.value).name" ')}${select('policyMode','Ao trocar o produto',[['keep','Manter valores e percentuais contratados'],['replace','Aplicar política atual do novo produto']], 'keep')}${field('start','Data de ativação',c.start,'date','required')}${canManage('Comissões')?select('commissionPayer','Responsável pelas comissões deste contrato',[['','Não definido'],...paymentPeople(c.company,c.commissionPayer).map(u=>[u.id,u.name+' · '+((u.role==='Administrador'||u.all)?'Gestão da plataforma':'Gestão da empresa')])],c.commissionPayer||''):''}${['seller','dev','partner'].map(k=>select(k,({seller:'Vendedor',dev:'Desenvolvedor',partner:'Parceiro'})[k],[['','Não atribuído'],...state.users.filter(u=>u.active&&(u.all||u.companies.includes(c.company))||u.id===c[k]).map(u=>[u.id,u.name])],c[k]||'')).join('')}</div><div class="notice">O responsável do contrato se aplica a todas as comissões ainda não pagas, inclusive futuras mensalidades e implementação. Pagamentos já registrados preservam o responsável original.</div><div class="notice">Escolha outro produto da mesma empresa. Por padrão, os valores e percentuais contratados são mantidos. Aplicar a política do novo produto recalcula as comissões e exige cobranças ainda não recebidas. Valores das cobranças são alterados em Recebíveis.</div><div class="checks"><label><input type="checkbox" name="started" ${c.started?'checked':''}> Implantação iniciada</label><label><input type="checkbox" name="accepted" ${c.accepted?'checked':''}> Aceite / go-live registrado</label></div>${product(c.product)?.type==='Recorrente'?btn('Adicionar próxima mensalidade',`extendContract(${contractIdLiteral(c.id)})`,true):''}${actions()}</form>`,f=>{try{updateContractDetails(id,{client:f.get('client'),plan:f.get('plan'),product:f.get('product'),policyMode:f.get('policyMode'),commissionPayer:canManage('Comissões')?f.get('commissionPayer'):undefined,seller:f.get('seller'),dev:f.get('dev'),partner:f.get('partner'),start:f.get('start'),started:f.has('started'),accepted:f.has('accepted')});closeSaved('Detalhes do contrato atualizados.');}catch(e){toast(e.message)}});}
function updateContractDetails(id,data){if(!canManage('Contratos'))throw Error('Sem permissão.');const c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company))throw Error('Contrato indisponível.');const client=String(data.client||'').trim(),plan=String(data.plan||'').trim();if(!client||!plan||!validDate(data.start))throw Error('Informe cliente, plano e uma data válida.');if(data.accepted&&!data.started)throw Error('Registre o início antes do aceite.');if(ledger().some(x=>x.contract.id===id&&x.paidAt&&((x.label==='Implementação · aceite'&&!data.accepted)||(x.label.startsWith('Implementação ·')&&!data.started))))throw Error('Há comissão paga nesta etapa. Desfaça o pagamento antes de alterar.');for(const key of ['seller','dev','partner'])if(data[key]!==undefined&&data[key]!==c[key]){if(ledger(true).some(x=>x.contract.id===id&&x.paidAt))throw Error('Desfaça os pagamentos antes de alterar os participantes.');if(data[key]&&!state.users.some(u=>u.id===data[key]&&u.active&&(u.all||u.companies.includes(c.company))))throw Error('Participante não vinculado à empresa.');}if(data.commissionPayer!==undefined&&data.commissionPayer!==c.commissionPayer){if(!canManage('Comissões'))throw Error('Atribuir o pagador exige acesso a Comissões.');if(data.commissionPayer&&!paymentPeople(c.company).some(u=>u.id===data.commissionPayer&&u.active))throw Error('Selecione um gestor com acesso à empresa.');}const next=product(data.product||c.product),changed=next?.id!==c.product;if(!next||next.company!==c.company||(next.archived&&changed)||c.archived)throw Error('Selecione um produto ativo da mesma empresa.');if(changed&&next.type!==product(c.product)?.type)throw Error('Selecione um produto com a mesma natureza de receita. Para mudar de recorrente para avulsa, cadastre outra venda.');if(changed&&data.policyMode==='replace'&&!canManage('Comissões'))throw Error('Alterar a política contratada exige acesso a Comissões.');if(changed&&data.policyMode==='replace'&&(state.invoices.some(i=>i.contractId===id&&i.paidAt)||ledger(true).some(x=>x.contract.id===id&&x.paidAt)))throw Error('Há recebimentos ou comissões pagas. Mantenha os percentuais contratados ou desfaça os pagamentos antes de aplicar outra política.');c.history??=[];c.history.push({action:'edit-details',client:c.client,plan:c.plan,product:c.product,rules:structuredClone(c.rules),version:c.version,start:c.start,started:c.started,accepted:c.accepted,at:new Date().toISOString(),by:currentUser});if(changed){c.policyProductName??=product(c.product)?.name;if(data.policyMode==='replace'){c.rules={...zeroRules,...structuredClone(next.rules)};c.version=next.version;c.policyProductName=next.name;}c.product=next.id;}for(const key of ['seller','dev','partner'])if(data[key]!==undefined)c[key]=data[key];if(data.commissionPayer!==undefined)c.commissionPayer=data.commissionPayer;Object.assign(c,{client,plan,start:data.start,started:!!data.started,accepted:!!data.accepted});save();}

function extendContract(id){if(!canManage('Contratos'))return;const c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company)||c.status!=='Ativo'||product(c.product)?.type!=='Recorrente')return toast('Contrato não elegível.');let last=state.invoices.filter(i=>i.contractId===id&&i.kind==='fee').sort((a,b)=>b.fee-a.fee)[0];if(!last)return;let fee=last.fee+1,due=addMonths(c.firstDue||last.due,c.firstDue?fee-1:1);state.invoices.push({id:uid('inv'),contractId:id,company:c.company,kind:'fee',fee,amount:c.monthly,due,paidAt:null});save();toast('Mensalidade '+fee+' gerada para '+due+'.');}
function duplicateContract(id){if(!canManage('Contratos'))return;const c=state.contracts.find(c=>c.id===id);if(c&&canAccess(c.company))newSale({...c,client:c.client+' (cópia)'});}

function goalActualFromSales(g){const end=addMonths(g.period+'-01',1),items=state.contracts.filter(c=>c.company===g.company&&!c.legacy&&!c.archived&&(!c.reviewStatus||c.reviewStatus==='approved'));const invoices=state.invoices.filter(i=>i.company===g.company&&!i.legacy&&!i.archived&&!invoiceContract(i)?.archived);return {actualClients:new Set(items.filter(c=>c.start.startsWith(g.period)&&!state.contracts.some(other=>!other.archived&&other.company===c.company&&other.client.trim().toLowerCase()===c.client.trim().toLowerCase()&&other.start<c.start)).map(c=>c.client.trim().toLowerCase())).size,actualRevenue:roundMoney(invoices.filter(i=>i.paidAt?.startsWith(g.period)).reduce((a,i)=>a+i.amount,0)),actualMrr:roundMoney(items.filter(c=>product(c.product)?.type==='Recorrente'&&c.start<end&&(c.status==='Ativo'||(c.cancelledAt&&c.cancelledAt>=end))).reduce((a,c)=>a+c.monthly,0))};}
function useSalesActuals(id){if(!canManage('Metas'))return;let g=state.goals.find(g=>g.id===id);if(!g||!canAccess(g.company))return;g.autoActual=!g.autoActual;save();render();toast(g.autoActual?'Realizado calculado pelas novas vendas.':'Realizado manual restaurado.');}
const renderGoalsManual=renderGoals;
renderGoals=function(){let original=state.goals;state.goals=original.map(g=>g.autoActual?{...g,...goalActualFromSales(g)}:g);let html;try{html=renderGoalsManual()}finally{state.goals=original}const list=scopedGoals().filter(g=>goalYear==='all'||g.period.startsWith(goalYear));return html+`<section class="panel" style="margin-top:20px"><h2>Origem do realizado</h2><p>Escolha por período: valores manuais ou novas vendas. No automático, o faturamento realizado usa o caixa recebido no mês, novos clientes contam a primeira ativação conhecida de cada cliente e o MRR considera produtos recorrentes ativos ao fim do mês. Referências migradas ficam excluídas para evitar mistura.</p>${table(['Empresa / mês','Origem','Ação'],list.map(g=>[esc(companyName(g.company))+' · '+esc(periodLabel(g.period)),g.autoActual?'Novas vendas · automático':'Manual / referência',btn(g.autoActual?'Usar manual':'Usar novas vendas',`useSalesActuals('${g.id}')`,true)]))}</section>`;};

function contractCode(c){return c.code||'CTR-'+String(c.id);}
function assignContractCodes(newContracts=[]){const all=[...state.contracts,...newContracts],used=new Set(all.filter(c=>c.code).map(c=>c.code));for(const c of all){if(c.code)continue;const year=(c.start||localToday()).slice(0,4),prefix='CTR-'+year+'-';let n=1;while(used.has(prefix+String(n).padStart(4,'0')))n++;c.code=prefix+String(n).padStart(4,'0');used.add(c.code);}}
function matchesContract(c,q){return !!c&&(!q||(contractCode(c)+' '+c.client).toLowerCase().includes(q.trim().toLowerCase()));}
function contractReference(c){return accessibleModules().includes('Contratos')?`<button class="contract-link" type="button" onclick="openSalePortal(${contractIdLiteral(c.id)})" title="Abrir venda e documentos">${esc(contractCode(c))} ↗</button>`:`<strong>${esc(contractCode(c))}</strong>`;}
function financeSearch(id,value,key){return `<div class="filters"><input id="${id}" type="search" aria-label="Buscar por contrato ou cliente" placeholder="Buscar código do contrato ou cliente…" value="${esc(value)}" oninput="${key}=this.value;refreshFinanceSearch('${id}')"></div>`;}
function refreshFinanceSearch(id){const input=document.getElementById(id),pos=input.selectionStart;render();const fresh=document.getElementById(id);fresh.focus();fresh.setSelectionRange(pos,pos);}
function extraCommissionRows(){return (state.extraCommissions||[]).filter(e=>!e.cancelled||state.commissionPayments[e.id]).flatMap(e=>{const c=state.contracts.find(c=>c.id===e.contractId),invoice=state.invoices.find(i=>i.id===e.invoiceId);if(!c||!invoice||invoice.contractId!==c.id||(c.archived||invoice.archived||c.reviewStatus&&c.reviewStatus!=='approved')&&!state.commissionPayments[e.id])return [];let stage=e.stage==='accepted'?c.accepted:e.stage==='started'?c.started:true;return [{id:e.id,manual:true,role:'extra',contract:c,invoice,person:e.person,amount:e.amount,label:'Extraordinária · '+(e.stage==='accepted'?'aceite':e.stage==='started'?'início da implantação':'recebimento'),reason:e.reason,rate:null,released:!!invoice.paidAt&&stage&&c.status==='Ativo'&&!c.archived&&!invoice.archived&&(!c.reviewStatus||c.reviewStatus==='approved'),paidAt:state.commissionPayments[e.id]||null}];});}
function newExtraCommission(){if(!canManage('Comissões'))return;const contracts=scope().filter(c=>c.status==='Ativo');if(!contracts.length)return toast('Cadastre um contrato ativo antes de lançar comissão.');show(`<h2>Comissão extraordinária</h2><p>Selecione um contrato existente. As comissões da política já são automáticas; use este lançamento somente para um valor adicional aprovado.</p><form><div class="formgrid">${field('contractSearch','Buscar contrato','', 'search','placeholder="Código ou cliente" oninput="filterExtraContracts(this.value)"')}${select('contract','Contrato',contracts.map(c=>[String(c.id),contractCode(c)+' · '+c.client+' · '+product(c.product)?.name]),String(contracts[0].id))}</div><div id="extraContext"></div><div id="extraFields"></div>${actions()}</form>`,f=>{try{createExtraCommission({contractId:Number(f.get('contract')),invoiceId:f.get('invoice'),person:f.get('person'),amount:Number(f.get('amount')),reason:f.get('reason'),stage:f.get('stage')});closeSaved('Comissão extraordinária vinculada ao contrato.');}catch(e){toast(e.message)}});document.getElementById('f_contract').onchange=()=>refreshExtraContext();refreshExtraContext();}
function filterExtraContracts(q){const contracts=scope().filter(c=>c.status==='Ativo'&&matchesContract(c,q));const el=document.getElementById('f_contract'),previous=el.value;el.innerHTML=contracts.map(c=>`<option value="${contractIdLiteral(c.id)}">${esc(contractCode(c)+' · '+c.client+' · '+product(c.product)?.name)}</option>`).join('');if(contracts.some(c=>String(c.id)===previous))el.value=previous;refreshExtraContext();}
function refreshExtraContext(){let c=state.contracts.find(c=>String(c.id)===document.getElementById('f_contract').value);if(!c||!canAccess(c.company)){document.getElementById('extraContext').innerHTML='<p>Nenhum contrato encontrado.</p>';document.getElementById('extraFields').innerHTML='';return;}const invoices=state.invoices.filter(i=>i.contractId===c.id&&!i.archived),people=[...new Set([c.seller,c.dev,c.partner].filter(Boolean))];document.getElementById('extraContext').innerHTML=`<div class="notice"><strong>${esc(contractCode(c))} · ${esc(c.client)}</strong><br>${esc(companyName(c.company))} · ${esc(product(c.product)?.name)} · política v${c.version}<br>Venda: ${c.rules.first}% no primeiro fee, ${c.rules.next}% até o fee ${c.rules.months}; implementação ${c.rules.setup}%. Desenvolvimento: primeiro fee ${c.rules.devFirst}%; pool ${c.rules.devSetup}%.<br>As comissões automáticas permanecem separadas deste adicional.</div>`;document.getElementById('extraFields').innerHTML=`<div class="formgrid">${select('invoice','Cobrança de referência',invoices.map(i=>[i.id,(i.kind==='fee'?'Fee '+i.fee:'Implementação · parcela '+(i.part||1))+' · '+i.due+' · '+money(i.amount)]),invoices[0]?.id)}${select('person','Participante do contrato',people.map(id=>[id,userName(id)]),people[0])}${field('amount','Comissão adicional (R$)','','number','required min=".01" step=".01"')}${select('stage','Liberar após', [['received','Recebimento da cobrança'],['started','Recebimento e início da implantação'],['accepted','Recebimento e aceite']], 'received')}${field('reason','Motivo / referência da aprovação','','text','required minlength="5" maxlength="500"')}</div>${people.length?'':'<p>Este contrato não possui participantes. Não é possível lançar comissão extraordinária.</p>'}`;}
function createExtraCommission(data){if(!canManage('Comissões'))throw Error('Sem permissão.');const c=state.contracts.find(c=>c.id===data.contractId),invoice=state.invoices.find(i=>i.id===data.invoiceId);if(!c||!canAccess(c.company)||c.status!=='Ativo'||!invoice||invoice.archived||invoice.contractId!==c.id)throw Error('Selecione um contrato e uma cobrança válidos.');if(![c.seller,c.dev,c.partner].filter(Boolean).includes(data.person))throw Error('Selecione um participante deste contrato.');const reason=String(data.reason||'').trim(),amount=roundMoney(data.amount);if(!Number.isFinite(amount)||amount<=0||reason.length<5||reason.length>500||!['received','started','accepted'].includes(data.stage))throw Error('Informe valor, condição e motivo válido para o adicional.');state.extraCommissions??=[];if(state.extraCommissions.some(e=>!e.cancelled&&e.contractId===c.id&&e.invoiceId===invoice.id&&e.person===data.person&&e.reason.toLowerCase()===reason.toLowerCase()))throw Error('Já existe um adicional com este motivo, participante e cobrança. Confira o lançamento existente.');const entry={id:uid('extra'),contractId:c.id,invoiceId:invoice.id,person:data.person,amount,reason,stage:data.stage,createdAt:localToday(),createdBy:currentUser};state.extraCommissions.push(entry);save();return entry;}


function invoiceEditable(i){return i&&!i.paidAt&&!ledger().some(x=>x.invoice.id===i.id&&x.paidAt);}
function updateInvoice(id,amount,due){if(!canManage('Recebíveis'))throw Error('Sem permissão.');const i=state.invoices.find(i=>i.id===id),c=i&&invoiceContract(i);if(!c||!canAccess(c.company)||i.archived)throw Error('Recebível indisponível.');if(!invoiceEditable(i))throw Error('Desfaça o pagamento das comissões e o recebimento antes de editar.');if(!Number.isFinite(amount)||amount<0||!validDate(due))throw Error('Informe valor e vencimento válidos.');i.history??=[];i.history.push({action:'edit',amount:i.amount,due:i.due,at:localToday(),by:currentUser});i.amount=roundMoney(amount);i.due=due;save();}
function editInvoice(id){if(!canManage('Recebíveis'))return;const i=state.invoices.find(i=>i.id===id),c=i&&invoiceContract(i);if(!c||!canAccess(c.company)||i.archived)return;if(!invoiceEditable(i))return toast('Desfaça o pagamento das comissões e o recebimento antes de editar.');show(`<h2>Editar recebível</h2><p>${esc(contractCode(c))} · ${esc(c.client)}</p><p>${esc(product(c.product)?.name)} · ${i.kind==='fee'?'Fee '+i.fee:'Implementação · parcela '+(i.part||1)}</p><div class="notice">A alteração vale apenas para esta cobrança e recalcula suas comissões previstas. Não altera os valores do contrato ou das demais parcelas.</div><form><div class="formgrid">${field('amount','Valor da cobrança (R$)',i.amount,'number','required min="0" step=".01"')}${field('due','Vencimento',i.due,'date','required')}</div>${actions()}</form>`,f=>{try{updateInvoice(id,Number(f.get('amount')),f.get('due'));closeSaved('Recebível atualizado; comissões recalculadas.');}catch(e){toast(e.message)}});}
function setInvoiceArchived(id,archived){if(!canManage('Recebíveis'))throw Error('Sem permissão.');const i=state.invoices.find(i=>i.id===id),c=i&&invoiceContract(i);if(!c||!canAccess(c.company))throw Error('Recebível indisponível.');if(archived&&!invoiceEditable(i))throw Error('Desfaça o pagamento das comissões e o recebimento antes de excluir.');i.archived=archived;i.history??=[];i.history.push({action:archived?'archive':'restore',at:localToday(),by:currentUser});save();}
function archiveInvoice(id){if(!canManage('Recebíveis'))return;const i=state.invoices.find(i=>i.id===id),c=i&&invoiceContract(i);if(!c||!canAccess(c.company)||i.archived)return;if(!invoiceEditable(i))return toast('Desfaça o pagamento das comissões e o recebimento antes de excluir.');show(`<h2>Excluir recebível</h2><p>${esc(contractCode(c))} · ${esc(c.client)} · ${money(i.amount)}</p><div class="notice">A cobrança e suas comissões previstas sairão dos totais. O contrato continuará ativo. Você poderá restaurar este recebível em “Recebíveis excluídos”.</div><form><div class="actions">${btn('Voltar',"document.getElementById('modal').close()",true)}<button class="btn" type="submit">Confirmar exclusão</button></div></form>`,()=>{try{setInvoiceArchived(id,true);closeSaved('Recebível excluído. Restauração disponível.');}catch(e){toast(e.message)}});}
function restoreInvoice(id){try{setInvoiceArchived(id,false);render();toast('Recebível e comissões previstas restaurados.');}catch(e){toast(e.message)}}
function archivedInvoicesPanel(){const list=state.invoices.filter(i=>i.archived&&invoiceContract(i)&&!invoiceContract(i).archived&&canAccess(i.company)&&(company==='all'||company===i.company)&&matchesContract(invoiceContract(i),invoiceQuery)&&(invoiceMonth==='all'||i.due.startsWith(invoiceMonth)));return list.length?`<section class="panel" style="margin-top:20px"><h2>Recebíveis excluídos</h2><p>Histórico preservado. Restaure uma cobrança para trazê-la de volta aos totais.</p>${table(['Contrato / cliente','Vencimento','Valor','Ação'],list.map(i=>[esc(contractCode(invoiceContract(i)))+' · '+esc(invoiceContract(i).client),esc(i.due),money(i.amount),btn('Restaurar',`restoreInvoice('${i.id}')`,true)]))}</section>`:'';}

state.commissionEdits??={};state.commissionPaymentDetails??={};state.commissionHistory??=[];
function ledger(includeArchived=false){return rawLedger().map(row=>{const edit=state.commissionEdits[row.id]||{},payment=state.commissionPaymentDetails[row.id]||{};return {...row,originalAmount:row.amount,amount:row.paidAt&&payment.amountPaid!==undefined?payment.amountPaid:edit.amount??row.amount,adjusted:edit.amount!==undefined,editReason:edit.reason||'',payer:row.paidAt?(payment.payer||edit.payer||''):(row.contract.commissionPayer!==undefined?row.contract.commissionPayer:edit.payer||''),paymentMethod:payment.method||'',plannedDate:edit.plannedDate||'',archived:!!edit.archived};}).filter(x=>includeArchived||!x.archived||x.paidAt);}
function paymentPeople(cid,selected){return state.users.filter(u=>(u.active&&['Administrador','Gestor'].includes(u.role)&&(u.role==='Administrador'||(u.modules||['Comissões']).includes('Comissões'))&&(u.all||u.companies.includes(cid)))||u.id===selected);}
function commissionHistory(id,action,before){state.commissionHistory.push({id,action,before:before?structuredClone(before):null,at:new Date().toISOString(),by:currentUser});}
function commissionDates(x){return `<div class="small">Venda: ${esc(x.contract.start||'—')}</div><div class="small">Vencimento cobrança: ${esc(x.invoice.due)}</div><div class="small">Recebido do cliente: ${esc(x.invoice.paidAt||'—')}</div><div class="small">Previsão de pagamento: ${esc(x.plannedDate||'—')}</div><div class="small">Comissão paga em: ${esc(x.paidAt||'—')}</div>`;}
function recordCommissionPayment(id,date,payer,method){if(!canManage('Comissões'))throw Error('Sem permissão.');const x=ledger().find(x=>x.id===id);if(!x||!canAccess(x.contract.company)||!x.released||x.paidAt||x.amount<=0)throw Error('Comissão indisponível para pagamento.');if(!validDate(date)||date>localToday()||date<x.invoice.paidAt)throw Error('A data deve estar entre o recebimento do cliente e hoje.');if(!canRecordPayment(x)||payer!==currentUser)throw Error('O pagamento deve ser confirmado pelo responsável designado.');if(!paymentMethods.includes(method))throw Error('Informe o meio de pagamento.');if(!paymentPeople(x.contract.company).some(u=>u.id===payer))throw Error('Selecione um responsável com acesso à empresa.');state.commissionPayments[id]=date;state.commissionPaymentDetails[id]={payer,method,payerName:userName(payer),recordedBy:currentUser,recordedAt:new Date().toISOString()};commissionHistory(id,'payment');save();}
function editCommission(id){if(!canManage('Comissões'))return;const x=ledger().find(x=>x.id===id);if(!x||!canAccess(x.contract.company))return;show(`<h2>Editar comissão</h2><p>${esc(contractCode(x.contract))} · ${esc(userName(x.person))} · ${esc(x.label)}</p><div class="notice">${x.paidAt?'O valor está pago. Você pode corrigir o responsável e a data; desfaça o pagamento para ajustar o valor.':'O ajuste será aplicado somente a esta comissão, preservando a política original do contrato.'}</div><form><div class="formgrid">${field('amount','Valor da comissão (R$)',x.amount,'number',`required min="0" step=".01" ${x.paidAt?'readonly':''}`)}${!x.paidAt&&x.contract.commissionPayer!==undefined?`<div class="field"><label>Responsável pelo contrato</label><p>${esc(x.payer?userName(x.payer):'Não definido')}</p><input type="hidden" name="payer" value="${esc(x.payer)}"><p class="small">Altere o responsável em Editar contrato para aplicar às parcelas em aberto.</p></div>`:select('payer','Responsável pelo pagamento',[['','Não definido'],...paymentPeople(x.contract.company,x.payer).map(u=>[u.id,u.name])],x.payer)}${field('plannedDate','Previsão de pagamento',x.plannedDate,'date')}${x.paidAt?field('paidDate','Data do pagamento',x.paidAt,'date','required')+select('method','Meio de pagamento',[['','Selecione'],...paymentMethods.map(v=>[v,v])],x.paymentMethod):''}${field('reason','Motivo da alteração','','text','required minlength="5" maxlength="500"')}</div><h3 style="font-size:13px;margin-top:22px">Datas de referência</h3>${commissionDates(x)}${actions()}</form>`,f=>{try{updateCommission(id,{amount:Number(f.get('amount')),payer:f.get('payer'),plannedDate:f.get('plannedDate'),paidDate:f.get('paidDate'),method:f.get('method'),reason:f.get('reason')});closeSaved('Comissão atualizada. Alteração registrada no histórico.');}catch(e){toast(e.message)}});}
function updateCommission(id,data){if(!canManage('Comissões'))throw Error('Sem permissão.');const x=ledger().find(x=>x.id===id);if(!x||!canAccess(x.contract.company))throw Error('Comissão indisponível.');const amount=roundMoney(data.amount),reason=String(data.reason||'').trim();if(!Number.isFinite(amount)||amount<0||reason.length<5||reason.length>500)throw Error('Informe um valor válido e o motivo da alteração.');if(x.paidAt&&(!canRecordPayment(x)||data.payer!==x.payer))throw Error('Somente o responsável pode corrigir o registro de pagamento.');if(x.paidAt&&!paymentMethods.includes(data.method))throw Error('Informe o meio de pagamento.');if(x.paidAt&&amount!==x.amount)throw Error('Desfaça o pagamento antes de alterar o valor.');if(data.plannedDate&&!validDate(data.plannedDate))throw Error('Previsão de pagamento inválida.');if(data.payer&&!paymentPeople(x.contract.company,x.payer).some(u=>u.id===data.payer))throw Error('Responsável inválido.');if(x.paidAt&&(!data.payer||!validDate(data.paidDate)||data.paidDate>localToday()||data.paidDate<x.invoice.paidAt))throw Error('Informe responsável e data entre o recebimento do cliente e hoje.');commissionHistory(id,'edit',{amount:x.amount,payer:x.payer,plannedDate:x.plannedDate,paidAt:x.paidAt});const edit={...state.commissionEdits[id],payer:data.payer||'',plannedDate:data.plannedDate||'',reason};if(amount!==x.amount||x.adjusted)edit.amount=amount;state.commissionEdits[id]=edit;if(x.paidAt){state.commissionPayments[id]=data.paidDate;state.commissionPaymentDetails[id]={...state.commissionPaymentDetails[id],method:data.method,payer:data.payer,payerName:userName(data.payer),updatedBy:currentUser,updatedAt:new Date().toISOString()};}save();}
function setCommissionArchived(id,archived){if(!canManage('Comissões'))throw Error('Sem permissão.');const x=ledger(true).find(x=>x.id===id);if(!x||!canAccess(x.contract.company))throw Error('Comissão indisponível.');if(x.paidAt)throw Error('Desfaça o pagamento antes de excluir a comissão.');commissionHistory(id,archived?'archive':'restore');state.commissionEdits[id]={...state.commissionEdits[id],archived};save();}
function archiveCommission(id){if(!canManage('Comissões'))return;const x=ledger().find(x=>x.id===id);if(!x||!canAccess(x.contract.company))return;if(x.paidAt)return toast('Desfaça o pagamento antes de excluir a comissão.');show(`<h2>Excluir comissão</h2><p>${esc(contractCode(x.contract))} · ${esc(userName(x.person))} · ${money(x.amount)}</p><div class="notice">Somente este lançamento sairá dos totais. Contrato, recebível e outras comissões serão preservados. Você poderá restaurá-lo em “Comissões excluídas”.</div><form><div class="actions">${btn('Voltar',"document.getElementById('modal').close()",true)}<button type="submit" class="btn">Confirmar exclusão</button></div></form>`,()=>{try{setCommissionArchived(id,true);closeSaved('Comissão excluída. Restauração disponível.');}catch(e){toast(e.message)}});}
function restoreCommission(id){try{setCommissionArchived(id,false);render();toast('Comissão restaurada.');}catch(e){toast(e.message)}}
function archivedCommissionPanel(){if(!canManage())return '';const rows=ledger(true).filter(x=>x.archived&&canAccess(x.contract.company)&&(company==='all'||company===x.contract.company)&&matchesContract(x.contract,commissionQuery)&&(commissionMonth==='all'||commissionDate(x)?.startsWith(commissionMonth)));return rows.length?`<section class="panel" style="margin-top:20px"><h2>Comissões excluídas</h2>${table(['Contrato','Participante','Valor','Ação'],rows.map(x=>[esc(contractCode(x.contract)),esc(userName(x.person)),money(x.amount),btn('Restaurar',`restoreCommission('${x.id}')`,true)]))}</section>`:'';}
assignContractCodes();save();render();

function setContractArchived(id,archived){if(!canManage('Contratos'))throw Error('Sem permissão.');const c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company))throw Error('Contrato indisponível.');c.history??=[];c.history.push({action:archived?'archive':'restore',at:new Date().toISOString(),by:currentUser});c.archived=archived;save();}
function archiveContract(id){if(!canManage('Contratos'))return;const c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company))return;show(`<h2>Excluir contrato</h2><p>${esc(contractCode(c))} · ${esc(c.client)}</p><div class="notice">O contrato sairá da lista operacional. Comissões já pagas e seus valores continuarão no extrato; previsões não pagas serão ocultadas. Os demais contratos da venda não serão excluídos.</div><form><div class="actions">${btn('Voltar',"document.getElementById('modal').close()",true)}<button type="submit" class="btn">Confirmar exclusão</button></div></form>`,()=>{try{setContractArchived(id,true);closeSaved('Contrato excluído. Restaure em Contratos excluídos.');}catch(e){toast(e.message)}});}
function restoreContract(id){try{setContractArchived(id,false);render();toast('Contrato e seus vínculos restaurados.');}catch(e){toast(e.message)}}
function archivedContractsPanel(){const list=state.contracts.filter(c=>c.archived&&canAccess(c.company)&&(company==='all'||company===c.company));return list.length?`<section class="panel" style="margin-top:20px"><h2>Contratos excluídos</h2><p>Histórico e pagamentos preservados. Restaurar também traz de volta os recebíveis e comissões vinculados que não tenham sido excluídos individualmente.</p>${table(['Código / cliente','Empresa','Ação'],list.map(c=>[esc(contractCode(c))+' · '+esc(c.client),esc(companyName(c.company)),btn('Restaurar',`restoreContract(${contractIdLiteral(c.id)})`,true)]))}</section>`:'';}

function matchesCommissionFilters(x){const status=x.paidAt?'paid':x.released?'released':'pending';const type=x.manual?'extra':x.invoice.kind==='setup'?'setup':'fee';return !!commissionDate(x)&&(commissionMonth==='all'||commissionDate(x)?.startsWith(commissionMonth))&&matchesContract(x.contract,commissionQuery)&&(commissionPerson==='all'||x.person===commissionPerson)&&(commissionStatus==='all'||status===commissionStatus)&&(commissionContract==='all'||String(x.contract.id)===commissionContract)&&(commissionType==='all'||type===commissionType);}
function commissionFilterBar(all){const people=[...new Set(all.map(x=>x.person))],contracts=[...new Map(all.map(x=>[String(x.contract.id),x.contract])).values()];const filter=(name,label,options,value)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" onchange="${name}=this.value;render()">${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></div>`;return `<div class="commission-filter-bar">${filter('commissionPerson','Colaborador',[['all','Todos os colaboradores'],...people.map(id=>[id,userName(id)])],commissionPerson)}${filter('commissionStatus','Status',[['all','Todos os status'],['pending','Prevista · pendente'],['released','Liberada · a pagar'],['paid','Paga']],commissionStatus)}${filter('commissionContract','Contrato',[['all','Todos os contratos'],...contracts.map(c=>[String(c.id),contractCode(c)+' · '+c.client])],commissionContract)}${filter('commissionType','Tipo',[['all','Todos os tipos'],['fee','Mensalidade / venda'],['setup','Implementação'],['extra','Extraordinária']],commissionType)}${btn('Limpar filtros','clearCommissionFilters()',true)}</div>`;}
function clearCommissionFilters(){commissionPerson=commissionStatus=commissionContract=commissionType=commissionMonth='all';commissionDateBasis='due';commissionQuery='';render();}

function commissionDate(x){return ({due:x.invoice.due,received:x.invoice.paidAt,planned:x.plannedDate,paid:x.paidAt,sale:x.contract.start})[commissionDateBasis]||null;}
function commissionDateLabel(){return ({due:'Vencimento da cobrança',received:'Recebimento do cliente',planned:'Previsão de pagamento',paid:'Pagamento da comissão',sale:'Data da venda'})[commissionDateBasis];}
function commissionDateFilter(){return `<div class="filters"><label for="commissionDateBasis">Data de referência</label><select id="commissionDateBasis" onchange="commissionDateBasis=this.value;commissionMonth='all';render()">${Object.entries({due:'Vencimento da cobrança',received:'Recebimento do cliente',planned:'Previsão de pagamento',paid:'Pagamento da comissão',sale:'Data da venda'}).map(([id,name])=>`<option value="${id}" ${commissionDateBasis===id?'selected':''}>${name}</option>`).join('')}</select></div>`;}
